import fs from 'node:fs';
import path from 'node:path';
import { HEADERS,column } from '../src/crm.mjs';
import { root } from '../src/config.mjs';
const meaning={
 'Lead ID':'Generated canonical-domain SHA-256 identifier. Do not edit.',Company:'Publicly supported company name; manual seed is unverified until research.',Website:'Editable public company website; normalized to HTTPS domain.',Country:'Publicly verified literal location, otherwise blank.',
 'Contact Name':'Optional public contact name entered and verified by you. Not used in generated greeting.','Contact Role':'Optional relevant public role entered and verified by you.',Email:'Public contact email, or owned recipient in test mode.',Industry:'Literal public source text, otherwise blank.','Business Description':'Exact public observations joined together.',
 'Verified Observations':'JSON array of {quote,url}; exact quotes checked against local snapshots.','Source URLs':'JSON array of collected public source URLs.','Possible IT Opportunity':'AI hypothesis to discuss; never a verified problem.','Recommended Service':'One allowed deliverable service, otherwise blank.',Confidence:'low/medium/high evidence strength from AI; review required.',
 'Score Inputs':'JSON object keyed by relevance,need,decisionMaker,budget,timing; values points,reason,quote,url.','Score Reviewed':'Editable true/false. You confirm scored source evidence.','Delivery Confirmed':'Editable true/false. You confirm ability to deliver that service.','Lead Score':'Computed integer 0..12.',Category:'Computed A/B/C.','Score Explanation':'Deterministic explanation for all six score components.',
 'Lead Status':'new, researched, qualified, additional research, duplicate, suppressed, reply received, manual review.','Research Allowed':'Editable true/false; review source access terms first.','Contact Verified':'Editable true/false; verify recipient and public email.','Outreach Approved':'Editable true/false; permit draft preparation only.','Follow-up Allowed':'Editable true/false; can be revoked, but cannot override replies/opt-outs.',
 'Researched Date':'ISO 8601 timestamp of verified research.','Created Date':'ISO 8601 creation timestamp.','Last Error':'Last lead-level error, safe text without secrets.',
 'Operation ID':'Immutable Lead ID:Stage key; stage0 initial, stage1 first follow-up, stage2 final.','Draft ID':'Actual Gmail draft ID returned/recovered from API.','Gmail Thread ID':'Actual Gmail thread ID.','Sent Message ID':'Actual SENT message ID verified by reconciliation.','Sent Date':'Actual Gmail internalDate converted to ISO; blank before real sending.',Stage:'Integer 0/1/2 for this specific outreach operation.','Next Follow-up Date':'4 days after initial send or 7 days after first follow-up send; blank if blocked/final.','Reply Status':'Interested, Meeting requested, Needs more information, Not interested, Opt-out, Uncertain / manual review.','Draft Status':'draft or sent. Do not fake sent to advance sequence.',Reference:'Unique visible Reference footer token for recovery.','Message-ID':'Unique RFC Message-ID assigned before draft POST.',
 Reason:'Opt-out/manual suppression reason.','Suppression Date':'ISO 8601 suppression timestamp.','Event ID':'Unique event key; stable keys for send/draft/reply deduplication.',Timestamp:'ISO 8601 event timestamp.',Workflow:'Helper task or n8n error workflow name.',Action:'Business event such as researched, qualified, draft created, sent or reply category.',Outcome:'success or error.',Error:'Safe diagnostic text; no tokens, raw API bodies or secrets.',
 Date:'Karachi calendar date YYYY-MM-DD.','New Leads Researched':'Successful researched events today.','Qualified Leads':'New A qualification events today.','Drafts Awaiting Review':'Current CRM drafts (not a count of sends).','Emails Actually Sent':'New verified SENT events today.','Interested Responses':'New rule-confirmed interested replies today.','Follow-ups Due':'Currently eligible/due operations.','Meetings Needing Attention':'Current Meeting requested CRM records.','Workflow Errors':'Error events today, including lead-level batch failures.'
};
let doc='# Exact Google Sheets CRM mapping\n\nRow 1 must contain these exact case-sensitive headers in this order. The workbook and CSV templates match the `HEADERS` constant in src/crm.mjs. Data begins on row 2; there are no title rows above the headers. n8n calls `/jobs` with a task name and the local helper maps fields by header. RAW writes keep source text literal. Never rename tabs or headers, duplicate keys or manually edit identifier/send-proof fields.\n\nBoolean controls use true/false (strings or native booleans); dates use ISO timestamps. JSON fields are plain cell text and must remain valid JSON. Empty source evidence stays blank rather than being fabricated. Google Sheets is the CRM; the local journal is recovery state.\n';
doc+='\nThe existing workbook/CSV templates contain the original five tabs. Optional TRACKING is added separately with `npm run tracking:crm`; templates are unchanged. In TRACKING, Sent Date can be UI-reported or manually confirmed. Only Send Confirmation `gmail_sent_verified` means actual Gmail SENT proof. Image Requests is not a human open count.\n';
const trackingMeaning={'Tracking ID':'Unique hosted record ID.','Operation ID':'Agency Lead ID:Stage; blank for standalone extension messages.','Lead ID':'Agency ID or unique recipient-email CRM match; blank if ambiguous.',Company:'CRM company or optional user label.',Email:'Original single recipient; does not identify the viewer.',Subject:'Email subject; no body is stored.',Source:'extension or agency.','Send Confirmation':'gmail_ui, gmail_sent_verified or manual.','Sent Date':'Reported timestamp; see Send Confirmation for verification type.','Tracking State':'draft, confirmed, disabled or cancelled.','First Possible Open':'First image request after confirmation and 45-second buffer.','Last Image Request':'Latest eligible image-request timestamp.','Image Requests':'Image fetch count; not proof of human opening.','Last Synced':'CRM sync timestamp.'};
for(const [tab,headers]of Object.entries(HEADERS)){doc+=`\n## ${tab}\n\n| Column | Exact header | Mapping / meaning |\n|---|---|---|\n`;headers.forEach((h,i)=>{doc+=`| ${column(i)} | ${h} | ${(tab==='TRACKING'?trackingMeaning[h]:meaning[h]) || h} |\n`;});}
doc+='\nManual intake: Company, Website, Country and optional Email are sufficient. Import defaults approvals to false and assigns Lead ID. Research overwrites company/country with verified public values, saves exact observations, score suggestions and dates. Qualification writes score/category/explanation after your review. Draft/reconcile/reply/follow-up jobs upsert OUTREACH by Operation ID. Suppression is keyed by normalized email and mirrored to the local journal. ACTIVITY LOG is keyed by Event ID. REPORTS is upserted by local Date.\n';
fs.writeFileSync(path.join(root,'docs/crm-columns.md'),doc);console.log('Generated exact CRM column mapping.');
